  check: svg('<path d="m5.5 12.5 4 4 9-9.5"/>'),
  xmark: svg('<path d="M6.5 6.5l11 11M17.5 6.5l-11 11"/>'),
  sparkle: svg('<path d="M12 3.5c.5 3.6 2.4 5.6 6 6.2-3.6.6-5.5 2.6-6 6.3-.5-3.7-2.4-5.7-6-6.3 3.6-.6 5.5-2.6 6-6.2z"/><path d="M18.5 15.5c.2 1.4.9 2.1 2.2 2.3-1.3.2-2 1-2.2 2.4-.2-1.4-.9-2.2-2.2-2.4 1.3-.2 2-.9 2.2-2.3z"/>'),
  doc: svg('<path d="M7 3.5h6.8L19 8.7V18a2.5 2.5 0 0 1-2.5 2.5h-9.5A2.5 2.5 0 0 1 4.5 18V6A2.5 2.5 0 0 1 7 3.5z"/><path d="M13.5 3.8V9H19M8.5 13h7M8.5 16.5h4.5"/>'),
  cards: svg('<rect x="4" y="8" width="16" height="12.5" rx="2.6"/><path d="M6.5 5h11M8.5 2.5h7"/>'),
